{
  "predictors": [
    {
      "name": "Revenue Growth Stability",
      "construction": "Calculate the standard deviation of quarterly revenue growth rates over the past 5 years.",
      "rationale": "Firms with stable revenue growth may be better at managing operations and demand, leading to more predictable cash flows.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Use employee satisfaction scores from company surveys or third-party sources, averaged over the past 3 years.",
      "rationale": "Firms with higher employee satisfaction may experience higher productivity and lower turnover costs, leading to better performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Count the number of citations made to a firm’s patents, averaged over the past year.",
      "rationale": "Firms whose patents are frequently cited may have more valuable and innovative technologies, indicating future growth potential.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Diversity Ratio",
      "construction": "Calculate the proportion of total procurement spending across multiple suppliers over the past year.",
      "rationale": "Firms with diverse supplier bases may be less vulnerable to supply chain disruptions, leading to more stable operations.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Gender Diversity",
      "construction": "Calculate the percentage of female board members as of the most recent fiscal year-end.",
      "rationale": "Gender-diverse boards might bring diverse perspectives and improve decision-making, potentially enhancing company performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Sentiment",
      "construction": "Analyze the sentiment of social media mentions using a natural language processing algorithm, averaged over the past six months.",
      "rationale": "Positive social media sentiment can enhance brand image and customer loyalty, leading to improved market performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Compliance Record",
      "construction": "Count the number of environmental violations recorded over the past 3 years.",
      "rationale": "Firms with fewer environmental violations are likely to face fewer legal and regulatory costs, preserving profitability.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Product Recall Frequency",
      "construction": "Count the number of product recalls over the past 5 years.",
      "rationale": "Firms with fewer recalls may have better quality control and brand reputation, which can enhance customer retention and revenue stability.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "R&D Expense Consistency",
      "construction": "Calculate the coefficient of variation of R&D expenses over the past 7 years.",
      "rationale": "Consistent R&D spending may indicate a steady commitment to innovation, potentially leading to a sustainable competitive advantage.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Tech Adoption Speed",
      "construction": "Measure the time taken by the firm to adopt new industry-relevant technologies, averaged over the past 10 years.",
      "rationale": "Firms faster at adopting new technologies may remain competitive and capitalize on technological advancements more effectively.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
